SELECT DISTINCT m.chembl_id AS compound_chembl_id, s.canonical_smiles FROM target_dictionary t JOIN assays a ON a.tid = t.tid JOIN activities act ON act.assay_id = a.assay_id JOIN molecule_dictionary m ON act.molregno = m.molregno JOIN compound_structures s ON s.molregno = m.molregno WHERE t.chembl_id = 'CHEMBL2971' AND a.assay_organism = 'Homo sapiens' ORDER BY compound_chembl_id, canonical_smiles
